;------------------------------------------------------------------------------; Scripteur ......: Daniel Lafrance, Québec, canada.; Nom du fichier .: l-c64-joystick.asm; Cernière m.à j. : 20261030-000000 Francisation des commentaires,; Inspiration ....:;------------------------------------------------------------------------------; Ces fonctions nécessite l'inclusion des variables contenue dans:;              .include "v_c64_showregs.asm"; Ces fonction utilise les routines de conversion contenues dans:;              .include "l-cbm-conv.asm";------------------------------------------------------------------------------; On prend une photo de tous les registres et on les place en mémoire.;------------------------------------------------------------------------------regxloc        = 13regyloc        = 8printregs      .macro               jsr   regsphoto               #locate 9,6               #outstr reg_titre               #locate regxloc,regyloc                jsr   showregs               #locate regxloc-2,24               #outstr contstr               #brkpoint 'c'               .endmligneplus     .macro coln               jsr   push               sec               jsr   plot               inx               ldy   #\coln               clc               jsr   plot               jsr   pop               .endmregsphoto      .block               php                  ; Sauve le registre P. stack-> p, pch, pcl               sta   vrega          ; Sauve Acc en mémoire.               pla                  ; stack-> pcl, pch               sta   vregp          ; Sauve P en mémoire.               stx   vregx          ; Sauve X en mémoire.               sty   vregy          ; Sauve Y en mémoire.               tsx                  ; Copie S san X.               stx   vregs          ; Sauve S en mémoire.               pla                  ; Récupère pcl. stack-> pch                    sta   vregpcl        ; Sauve pcl en mémoire.                pla                  ; Récupère pch. stack->                sta   vregpch        ; Sauve pch en mémoire.               lda   vrega          ; conversion de A en hexadecimal               pha                  ; stack-> a               lda   zpage1         ; Fais une copie du LSB de zpage1               sta   vzp1l          ; ... mémoire.               lda   zpage1+1       ; Fais une copie du MSB de zpage1               sta   vzp1h          ; ... mémoire.               lda   zpage2         ; Fais une copie du LSB de zpage2               sta   vzp2l          ; ... mémoire.               lda   zpage2+1       ; Fais une copie du MSB de zpage2               sta   vzp2h          ; ... mémoire.               lda   vregpch        ; Récupère le MSB du PC et le remet                pha                  ; ... sur la pile. stack-> pch               lda   vregpcl        ; Récupère le LSB du PC et le remet                pha                  ; ... sur la pile. stack-> pcl, pch               ldy   vregy          ; Récupère la valeur de Y.               ldx   vregx          ; Récupère la valeur de X.               lda   vregp          ; Récupère la valeur du registre de status               pha                  ; ... remet sur stack-> p, pcl, pch               lda   vrega          ; Récupère la valeur de l'Acc.               plp                  ; Récupère le status. stack-> pcl, pch               rts                  ; L'adresse de retour est sur la pile.               .bendshowregs       .block               jsr   push               #outcar  b_blanc                    clc               inc   vregpcl               bcc   norep               inc   vregpch               #ligneplus  regxlocnorep          lda   vrega               #outstr ra_str               jsr   putahexfmt               #ligneplus  regxloc               lda   vregx               #outstr rx_str               jsr   putahexfmt               #ligneplus  regxloc                              lda   vregy               #outstr ry_str               jsr   putahexfmt               #ligneplus  regxloc                              lda   vregp               #outstr sr_str               jsr   putahexfmt               #ligneplus  regxloc                              lda   vregs               #outstr sp_str               jsr   putahexfmt               #ligneplus  regxloc                              ldy   vregpch               ldx   vregpcl               jsr   yxtohex               #outstr pc_str               #outstr  a2hexpfx               #ligneplus  regxloc               ldy   vzp1h               ldx   vzp1l               jsr   yxtohex               #outstr z1_str               #outstr  a2hexpfx               #ligneplus  regxloc               ldy   vzp2h               ldx   vzp2l               jsr   yxtohex               #outstr z2_str               #outstr  a2hexpfx               #ligneplus  regxloc               jsr   pop               rts               .bendreg_titre      .byte b_jaune               .null "contenu des registres"ra_str         .byte b_blanc               .text "a......: "               .byte b_vertp, 0 rx_str         .byte b_blanc               .text "x......: "                .byte b_vertp, 0 ry_str         .byte b_blanc               .text "y......: "                .byte b_vertp, 0 sr_str         .byte b_blanc               .text "sr.....: "                .byte b_vertp, 0 sp_str         .byte b_blanc               .text "sp.....: "                .byte b_vertp, 0 pc_str         .byte b_blanc               .text "pc.....: "                .byte b_vertp, 0 z1_str         .byte b_blanc               .text "zpage1.: "                .byte b_vertp, 0 z2_str         .byte b_blanc               .text "zpage2.: "                .byte b_vertp, 0 contstr        .byte b_rose               .text "[c] pour continuer"               .byte b_blanc, 0